import { Area } from 'react-easy-crop'

export const isMenuActive = (
  menu: { path: string; children?: { [key: string]: string; path: string }[]; [key: string]: any },
  pathname: string
): boolean => {
  return pathname.startsWith(menu.path) || (!!menu.children && menu.children.some(child => isMenuActive(child, pathname)))
}

export const getCroppedImg = (dataUrl: string, pixelCrop: Area, filename: string, type: string = 'image/jpeg') => {
  return new Promise((resolve, reject) => {
    const image = new Image()
    image.src = dataUrl
    image.crossOrigin = 'anonymous'
    image.onload = () => {
      const canvas = document.createElement('canvas')
      const ctx = canvas.getContext('2d')

      canvas.width = pixelCrop.width
      canvas.height = pixelCrop.height

      ctx.drawImage(image, pixelCrop.x, pixelCrop.y, pixelCrop.width, pixelCrop.height, 0, 0, pixelCrop.width, pixelCrop.height)

      // 获取 Base64 编码
      const base64Image = canvas.toDataURL(type)

      // 如果需要 File 对象
      canvas.toBlob(blob => {
        if (blob) {
          const file = new File([blob], filename, { type })
          // 可以将 file 返回，或者在这里处理
          resolve(file)
        }
      }, type)
    }

    image.onerror = error => {
      reject(error)
    }
  })
}

export const calcNumber = (length: string | number) => {
  if (typeof length === 'string') {
    if (length.includes('px')) {
      return parseInt(length.replace('px', ''))
    }
    return length.toString()
  }
  return length.toString()
}

export const replaceFilename = (file: File, filename: string) => {
  // 创建一个新的 Blob 对象，内容与旧文件相同
  const newFileBlob = new Blob([file], { type: file.type })

  // 创建一个新的 File 对象，使用新的文件名和旧文件的内容及类型
  return new File([newFileBlob], filename, {
    type: file.type,
    lastModified: file.lastModified
  })
}

