export const WebSiteUrlRegex = /^(https?:\/\/)?(www\.)?([a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}(\/[^\s]*)?$/

export const XUrlRegex = /^(https?:\/\/)?(www\.)?x\.com\/([a-zA-Z0-9_\/\-]*)$/

export const DiscordRegex = /^(https?:\/\/)?(www\.)?discord\.com(\/[a-zA-Z0-9_\/\-]*)?$/

export const TelegramRegex = /^(https?:\/\/)?(www\.)?(t\.me|telegram\.org)(\/[a-zA-Z0-9_\-]*)?$/
