import { useInitSDK } from '@cetus/hooks'
import envConfigs from '@cetus/types/src/config/envConfigs'
import { d } from '@cetus/utils'
import usePosHelper from './usePosHelper'
import useWrapPosData from './useWrapPosData'

export default function usePositionList() {
  const { clmmSdk } = useInitSDK()
  const { buildPositionType, buildFarmsPositionType, buildBurnPostionType } = usePosHelper()
  const { buildPosBaseInfo } = useWrapPosData()

  const getPositionList = async (account: string, tokens: any) => {
    const ownerRes = await clmmSdk.fullClient.getOwnedObjectsByPage(account, {
      options: { showType: true, showContent: true, showOwner: true },
      filter: {
        MatchAny: [
          {
            Package: envConfigs.clmm_sdk_options.clmm_pool.package_id
          },
          {
            StructType: buildFarmsPositionType
          },
          {
            StructType: buildBurnPostionType
          }
        ]
      }
    })

    console.log('🚀 ~ file: usePositionList.ts:25 ~ getPositionList ~ ownerRes:', ownerRes)

    const posBaseList: any = []

    for (const item of ownerRes.data as any[]) {
      const info = buildPosBaseInfo(item)
      if (d(info?.liquidity).lte(0)) continue
      if (!info?.displayTokenA || !info?.displayTokenB) continue
      if (info) {
        posBaseList.push(info)
      }
    }

    console.log('🚀 ~ file: usePositionList.ts:33 ~ getPositionList ~ posBaseList:', posBaseList)

    // const sortBaseList = posBaseList.sort((a, b) => b.version - a.version)

    // console.log('🚀 ~ file: usePositionList.ts:125 ~ getPositionList ~ posBaseList:', sortBaseList, posBaseList)
    // positionStore.setPositionBaseList(sortBaseList)

    // getPosRelatedData(posBaseList, tokens)
  }

  return {
    getPositionList
  }
}
