export const sleepTime = async (s: number) => {
  return new Promise(resolve => {
    setTimeout(() => {
      resolve(1)
    }, s)
  })
}

// 忽略大小写比较
export const ignoreCaseComparison = (str1: string | undefined, str2: string | undefined) => {
  return str1?.toUpperCase() === str2?.toUpperCase()
}

export function debounce(fn: any, wait: number) {
  let timer: any
  return (...args: any) => {
    // @ts-ignore
    // eslint-disable-next-line @typescript-eslint/no-this-alias
    const context = this
    if (timer) clearTimeout(timer)
    timer = setTimeout(() => {
      timer = null
      fn.apply(context, args)
    }, wait)
  }
}
/**
 *
 * @param input
 * @returns
 */
export function extractTokens(input: string): string[] {
  // 判断是否包含空格或者 -
  if (input.includes(' ') || input.includes('-')) {
    // 使用正则表达式匹配空格或者 -，并分割字符串
    const tokens = input.split(/\s+|-/)
    // 去除空字符串
    return tokens.filter(token => token.trim() !== '')
  } else {
    // 如果不包含空格或者 -，直接返回原始字符串
    return [input]
  }
}

function singleFormat(str: any) {
  return str.toString().length === 1 ? '0' + str : str
}

function getYMD(time: any) {
  const year = time.getFullYear()
  const month = time.getMonth() + 1
  const date = time.getDate()
  return year + '/' + singleFormat(month) + '/' + singleFormat(date)
}
function getMD(time: any) {
  const month = time.getMonth() + 1
  const date = time.getDate()
  return singleFormat(month) + '/' + singleFormat(date)
}
function getMDY(time: any) {
  const year = time.getFullYear()

  const month = time.getMonth() + 1
  const date = time.getDate()
  return singleFormat(month) + '/' + singleFormat(date) + '/' + new String(year).slice(2, 4)
}
function getHMS(time: any) {
  const hours = time.getHours()
  const minutes = time.getMinutes()
  const seconds = time.getSeconds()
  return singleFormat(hours) + ':' + singleFormat(minutes) + ':' + singleFormat(seconds)
}
function getHM(time: any) {
  const hours = time.getHours()
  const minutes = time.getMinutes()
  return singleFormat(hours) + ':' + singleFormat(minutes)
}
function getTimeZone(time: any) {
  const GTM_8 = 480 // -480
  const date = new Date(time)
  const subMin = date.getTimezoneOffset() + GTM_8
  date.setMinutes(date.getMinutes() + subMin)
  return date
}
export const timeFormat = (time: any, type?: any) => {
  if (time) {
    const date = getTimeZone(time)
    if (!type) return getYMD(date) + ' ' + getHMS(date)
    switch (type) {
      case 'HMS':
        return getHMS(date)
      case 'MDY':
        return getMDY(date)
      case 'YMD':
        return getYMD(date)
      case 'MD':
        return getMD(date)
      case 'HM':
        return getHM(date)
    }
  }
}

export const getTimeDifferenceString = (targetTimestamp: any) => {
  const targetTimestamps = Math.floor(targetTimestamp / 1000)
  const currentTimestamp = Math.floor(new Date().getTime() / 1000)

  const minute = 60
  const hour = 60 * minute
  const day = 24 * hour
  const month = 30 * day
  const year = 365 * day

  const timeDifference = currentTimestamp - targetTimestamps
  if (timeDifference < minute) {
    return 'recently'
  } else if (timeDifference < hour) {
    const minutesAgo = Math.floor(timeDifference / minute)
    if (minutesAgo == 1) {
      return `${minutesAgo} minute ago`
    } else {
      return `${minutesAgo} minutes ago`
    }
  } else if (timeDifference < day) {
    const hoursAgo = Math.floor(timeDifference / hour)
    if (hoursAgo == 1) {
      return `${hoursAgo} hour ago`
    } else {
      return `${hoursAgo} hours ago`
    }
  } else if (timeDifference < month) {
    const daysAgo = Math.floor(timeDifference / day)
    if (daysAgo == 1) {
      return `${daysAgo} day ago`
    } else {
      return `${daysAgo} days ago`
    }
  } else if (timeDifference < year) {
    const monthsAgo = Math.floor(timeDifference / month)
    if (monthsAgo == 1) {
      return `${monthsAgo} mouth ago`
    } else {
      return `${monthsAgo} mouths ago`
    }
  } else {
    const yearsAgo = Math.floor(timeDifference / year)
    if (yearsAgo == 1) {
      return `${yearsAgo} year ago`
    } else {
      return `${yearsAgo} years ago`
    }
  }
}

export function amountToBN(amount: string, decimals: number | undefined): BN {
  if (decimals === undefined) return new BN(0)
  if (amount === '' || d(amount).equals(0)) return new BN(0)
  const num = d(amount).mul(Math.pow(10, decimals)).toString()
  if (d(num).gte(1)) {
    return new BN(num)
  } else {
    throw Error('amountToBN value lt 1')
  }
}

export function amountToDecimalsNum(amount: string, decimals: number | undefined): string {
  if (decimals === undefined) return '0'
  if (amount === '' || d(amount).equals(0)) return '0'
  return d(amount).mul(Math.pow(10, decimals)).toString()
}

export function bnToAmount(amount: any, decimals: number | undefined): string {
  if (decimals === undefined) return ''
  const num = d(amount?.toString()).div(Math.pow(10, decimals)).toString()
  return num
}

export function isUserRejectedError(error: any) {
  try {
    return error && error.toString().includes('Rejected from user')
  } catch (error1) {
    console.log('🚀 ~ file: common.ts:214 ~ isUserRejectedError ~ error:', {
      error,
      error1
    })
    return false
  }
}

const ESlippageError = 1
const EStatusNotRaising = 3
const EBondingCurveNotMigrated = 4

export function isPumpSwapError(error: any, code: number) {
  const errorString = String(error)
  if (errorString.indexOf('Some("swap")') > -1 && errorString.indexOf(` }, ${code}`) > -1) {
    return true
  }
  return false
}

export function isPumpHasBurnError(error: any) {
  const errorString = String(error)
  if (errorString.indexOf('Some("burn_lp")') > -1 && errorString.indexOf(` }, ${EBondingCurveNotMigrated}`) > -1) {
    return true
  }
  return false
}

export function handleErrorMessages(error: any): string {
  if (isUserRejectedError(error)) {
    return 'User rejected the request'
  }
  if (isPumpSwapError(error, ESlippageError)) {
    return 'Exceed slippage'
  }

  if (isPumpSwapError(error, EStatusNotRaising)) {
    return 'The token has completed the burning curve. Please go to Cetus DEX for trading after migration.'
  }

  if (isPumpHasBurnError(error)) {
    return 'Liquidity already burned'
  }

  return 'Transaction failed'
}

export function isUpperCaseOrNumbersOrSymbols(str?: string): boolean {
  if (!str) {
    return false
  }
  return /^[A-Z0-9\W_]+$/.test(str)
}

export function parseOwnerBalanceChanges(
  response: SuiTransactionBlockResponse,
  owner?: string,
  includedFee: boolean = false
): Record<string, BalanceChanges> {
  const balanceChanges = response.balanceChanges
  const gasUsed = response.effects?.gasUsed
  const changeMap: Record<string, BalanceChanges> = {}

  let fee = '0'
  if (gasUsed) {
    fee = d(gasUsed.computationCost).add(gasUsed.storageCost).sub(gasUsed.storageRebate).mul(-1).toFixed(0)
  }

  if (balanceChanges) {
    balanceChanges.forEach((item: any) => {
      const coinType = extractStructTagFromType(item.coinType).full_address
      if (item.owner.AddressOwner === owner) {
        const isSuiCoin = CoinAssist.isSuiCoin(coinType)
        let amount = item.amount
        if (isSuiCoin) {
          amount = includedFee ? amount : d(amount).sub(fee).toFixed(0)
        }
        const info: BalanceChanges = {
          coinType,
          amount
        }
        changeMap[coinType] = info
      }
    })
  }

  return changeMap
}

export function getBalanceChanges(balanceChanges: Record<string, BalanceChanges>, coinInfo?: CoinInfo): string | undefined {
  if (coinInfo) {
    const obj = balanceChanges[extractStructTagFromType(coinInfo.coin_type).full_address]
    if (obj) {
      return fromDecimalsAmountFix(d(obj.amount).abs().toFixed(0), coinInfo.decimals)
    }
  }

  return undefined
}

export function downloadImage(base64Data: string, fileName = 'image.png') {
  const link = document.createElement('a')
  link.href = base64Data
  link.download = fileName
  link.click()
}

export function fallbackDownload(blob: any, fileName = 'image.png') {
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = fileName
  document.body.appendChild(link)
  link.click()
  document.body.removeChild(link)
  URL.revokeObjectURL(url)
}

export function coinMetadataToCoinInfo(metadata: CoinMetadata, coinType: string) {
  const coinInfo: CoinInfo = {
    id: metadata.id || undefined,
    logo_url: metadata.iconUrl || undefined,
    coin_type: coinType,
    decimals: metadata.decimals,
    description: metadata.description,
    name: metadata.name,
    symbol: metadata.symbol
  }

  return coinInfo
}
