import { IModule } from '@/interfaces/IModule'
import { CetusPumpSDK } from '@/sdk'
import {
  BondingCurve,
  BondingCurveStatus,
  BondingSwapAmountOptions,
  BurnLpOptions,
  CalculateSwapAmountOptions,
  CalculateSwapAmountResult,
  CompleteBondingCurveOptions,
  MediaTemplateValue,
  PublishTokenOptions,
  PumpGlobalConfig,
  StartBondingCurveOptions,
  TokenFee
} from '@/types/pump'
import { CompiledModule } from '@/utils/bytecode-template'
import {
  CLOCK_ADDRESS,
  TransactionUtil,
  d,
  extractStructTagFromType,
  getObjectFields,
  getPackagerConfigs,
  removeHexPrefix
} from '@cetusprotocol/cetus-sui-clmm-sdk'
import init, * as template from '@mysten/move-bytecode-template'
import url from '@mysten/move-bytecode-template/move_bytecode_template_bg.wasm?url'
import { Transaction } from '@mysten/sui/transactions'
import { fromHex, normalizeSuiObjectId } from '@mysten/sui/utils'
import { PumpUtils } from '..'

export class PumpModule implements IModule {
  protected _sdk: CetusPumpSDK

  constructor(sdk: CetusPumpSDK) {
    this._sdk = sdk
  }

  get sdk() {
    return this._sdk
  }

  async getPublishTokenFee(): Promise<TokenFee[]> {
    const { pump } = this._sdk.sdkOptions
    const { init_fees_handle } = getPackagerConfigs(pump)

    const cache = this._sdk.getCache<TokenFee[]>(init_fees_handle)
    if (cache) {
      return cache
    }

    const res = await this._sdk.fullClient.getDynamicFieldsByPage(init_fees_handle)
    const warpIds = res.data.map(item => item.objectId)
    if (warpIds.length > 0) {
      const res = await this._sdk.fullClient.batchGetObjects(warpIds, { showContent: true })
      const list = res.map(obj => {
        const fields = getObjectFields(obj)
        return {
          fee_coin_type: extractStructTagFromType(fields.name.fields.name).full_address,
          fee_amount: fields.value as string
        }
      })

      this._sdk.updateCache(init_fees_handle, list)

      return list
    }
    return []
  }

  async getBondingCurveById(bondingCurveId: string): Promise<BondingCurve | undefined> {
    try {
      const res = await this._sdk.fullClient.getObject({
        id: bondingCurveId,
        options: { showContent: true, showType: true }
      })

      const info = PumpUtils.buildBondingCurveInfo(res)
      this._sdk.updateCache(info.id, info)
      return info
    } catch (error) {
      console.log('🚀 ~ file: funModule.ts:24 ~ FunModule ~ getFunTokenInfo ~ error:', error)
      return this._sdk.getCache<BondingCurve>(bondingCurveId)
    }
  }

  async getBondingCurveByCoinType(coinType: string): Promise<BondingCurve | undefined> {
    const { pump } = this._sdk.sdkOptions
    const cacheKey = `getBondingCurveByCoinType_${coinType}`
    let id = this._sdk.getCache<string>(cacheKey)

    if (id === undefined) {
      const { coin_type_list_handle } = getPackagerConfigs(pump)
      try {
        const res: any = await this._sdk.fullClient.getDynamicFieldObject({
          parentId: coin_type_list_handle,
          name: {
            type: '0x1::type_name::TypeName',
            value: {
              name: removeHexPrefix(coinType)
            }
          }
        })

        id = res.data?.content?.fields.value
      } catch (error) {
        console.error('🚀 ~ file: pumpModule.ts:108 ~ PumpModule ~ getBondingCurveByCoinType ~ error:', error)
      }
    }

    if (id) {
      this._sdk.updateCache(cacheKey, id)
      return await this.getBondingCurveById(id)
    }

    return undefined
  }

  async getClmmPoolId(bondingCurveId: string, isBurn = false): Promise<string | undefined> {
    const cacheKey = `getClmmPoolId_${bondingCurveId}`
    let id = this._sdk.getCache<string>(cacheKey)

    if (id === undefined) {
      try {
        const res: any = await this._sdk.fullClient.getDynamicFieldObject({
          parentId: bondingCurveId,
          name: {
            type: '0x1::string::String',
            value: isBurn ? 'CetusLPBurnProof' : 'CetusClmmPosition'
          }
        })

        const fields = getObjectFields(res)

        id = isBurn ? fields.position.fields.pool : fields.pool

        if (id) {
          this._sdk.updateCache(cacheKey, id)
          return id
        }
      } catch (error) {
        console.log('🚀 ~ file: pumpModule.ts:108 ~ PumpModule ~ getClmmPoolId ~ error:', error)
      }
    }

    return id
  }

  async getGlobalConfig(): Promise<PumpGlobalConfig | undefined> {
    const { pump } = this._sdk.sdkOptions
    const { global_config_id } = getPackagerConfigs(pump)
    try {
      const res = await this._sdk.fullClient.getObject({
        id: global_config_id,
        options: { showContent: true, showType: true }
      })

      const info = PumpUtils.buildGlobalConfig(res)
      this._sdk.updateCache(global_config_id, info)
      return info
    } catch (error) {
      console.log('🚀 ~ file: funModule.ts:24 ~ FunModule ~ getGlobalConfig ~ error:', error)
      return this._sdk.getCache<PumpGlobalConfig>(global_config_id)
    }
  }

  async calculateSwapAmount(options: CalculateSwapAmountOptions): Promise<CalculateSwapAmountResult> {
    const { bonding_curve_id, amount, is_buy, by_amount_in, slippage, swap_fee_rate, init_price_config, uuid } = options

    console.log('🚀 ~ file: pumpModule.ts:170 ~ PumpModule ~ calculateSwapAmount ~ options:', options)

    let start_sqrt_price: string
    let current_sqrt_price: string
    let end_sqrt_price: string
    let liquidity: string
    let status

    if (init_price_config) {
      start_sqrt_price = init_price_config.start_sqrt_price
      current_sqrt_price = init_price_config.start_sqrt_price
      end_sqrt_price = init_price_config.end_sqrt_price
      liquidity = init_price_config.liquidity
      status = BondingCurveStatus.CREATED
    } else {
      const info = await this.getBondingCurveById(bonding_curve_id)
      start_sqrt_price = info!.start_sqrt_price
      current_sqrt_price = info!.current_sqrt_price
      end_sqrt_price = info!.end_sqrt_price
      liquidity = info!.liquidity
      status = info!.status
    }

    const res = PumpUtils.calculateCurveSwapAmount(
      start_sqrt_price,
      current_sqrt_price,
      end_sqrt_price,
      liquidity,
      swap_fee_rate,
      amount,
      by_amount_in,
      is_buy,
      slippage,
      status
    )

    return {
      ...res,
      is_buy,
      by_amount_in,
      uuid
    }
  }

  async buildPublishTokenPayload(options: PublishTokenOptions) {
    console.log('🚀 ~ file: pumpModule.ts:84 ~ PumpModule ~ buildPublishTokenPayload ~ options:', options)

    await init(url)
    const { pump } = this._sdk.sdkOptions
    const { tokenTicker, tokenName, tokenDescription, tokenIconUrl, tokenDiscordUrl, tokenWebsiteUrl, tokenTelegramLink, tokenTwitterLink, sig } =
      options
    const { token_bytecode_template, token_dependency } = getPackagerConfigs(pump)

    const bytecodeTpl = fromHex(token_bytecode_template)

    const compiledModule = new CompiledModule(template.deserialize(bytecodeTpl))
      .updateConstant(0, tokenTicker, 'TOKEN_SYMBOL', 'string')
      .updateConstant(1, tokenName, 'TOKEN_NAME', 'string')
      .updateConstant(2, tokenDescription, 'TOKEN_DESCRIPTION', 'string')
      .updateConstant(3, tokenIconUrl, 'TOKEN_ICON_URL', 'string')
      .updateConstant(4, tokenWebsiteUrl || MediaTemplateValue[0], MediaTemplateValue[0], 'string')
      .updateConstant(5, tokenTwitterLink || MediaTemplateValue[1], MediaTemplateValue[1], 'string')
      .updateConstant(6, tokenDiscordUrl || MediaTemplateValue[2], MediaTemplateValue[2], 'string')
      .updateConstant(7, tokenTelegramLink || MediaTemplateValue[3], MediaTemplateValue[3], 'string')
      .updateConstant(8, sig, 'SIGNATURE', 'string')
      .changeIdentifiers({
        TEMPLATE: tokenTicker.toUpperCase(),
        template: tokenTicker.toLowerCase()
      })

    const bytesToPublish = template.serialize(compiledModule.inner)

    const tx = new Transaction()
    tx.setGasBudget(100000000)
    const [upgradeCap] = tx.publish({
      modules: [[...bytesToPublish]],
      dependencies: token_dependency.map((id: string) => normalizeSuiObjectId(id))
    })

    tx.transferObjects([upgradeCap], tx.pure.address(this._sdk.senderAddress))

    return tx
  }

  /**
   * Swap
   * @param options
   * @returns
   */
  async buildBondingSwapPayload(options: BondingSwapAmountOptions, tx = new Transaction()): Promise<Transaction> {
    console.log('🚀 ~ file: pumpModule.ts:157 ~ PumpModule ~ buildBondingSwapPayload ~ options:', options)
    const { pump } = this._sdk.sdkOptions
    const { bonding_curve_id, token_coin_type, pay_coin_type, swap_result } = options

    const { amount_in, amount_out, fee_amount, is_buy, expect_rate_limit, by_amount_in } = swap_result

    const funName = is_buy
      ? by_amount_in
        ? 'swap_exact_input_sui'
        : 'swap_exact_output_meme'
      : by_amount_in
        ? 'swap_exact_input_meme'
        : 'swap_exact_output_sui'

    let pay_amount = '0'

    if (is_buy) {
      if (by_amount_in) {
        pay_amount = d(amount_in).add(fee_amount).toFixed(0)
      } else {
        pay_amount = PumpUtils.calculateAmountLimit(is_buy, swap_result)
      }
    } else {
      if (by_amount_in) {
        pay_amount = amount_in
      } else {
        pay_amount = PumpUtils.calculateAmountLimit(is_buy, swap_result)
      }
    }

    const { global_config_id } = getPackagerConfigs(pump)
    const suiAssetList = await this._sdk.fullClient.getOwnerCoinAssets(this._sdk.senderAddress, pay_coin_type)

    const payCoinObj = TransactionUtil.buildCoinForAmount(tx, suiAssetList, BigInt(d(pay_amount).toFixed(0)), pay_coin_type, false, true)

    tx.moveCall({
      target: `${pump.published_at}::router::${funName}`,
      arguments: [
        tx.object(global_config_id),
        tx.object(bonding_curve_id),
        payCoinObj.targetCoin,
        tx.pure.u64(by_amount_in ? pay_amount : amount_out),
        tx.pure.u128(expect_rate_limit),
        tx.object(CLOCK_ADDRESS)
      ],
      typeArguments: [token_coin_type]
    })

    return tx
  }

  buildBurnLpPayload(options: BurnLpOptions, tx = new Transaction()): Transaction {
    console.log('🚀 ~ file: pumpModule.ts:308 ~ PumpModule ~ buildBurnLpPayload ~ options:', options)

    const { pump } = this._sdk.sdkOptions
    const { bonding_curve_id, token_coin_type, clmm_coin_type_a, clmm_coin_type_b, clmm_pool_id } = options

    const { global_config_id, burn_manager_id } = getPackagerConfigs(pump)

    tx.moveCall({
      target: `${pump.published_at}::router::burn_lp`,
      arguments: [tx.object(global_config_id), tx.object(bonding_curve_id), tx.object(burn_manager_id), tx.object(clmm_pool_id)],
      typeArguments: [clmm_coin_type_a, clmm_coin_type_b, token_coin_type]
    })

    return tx
  }

  buildCompleteBondingCurvePayload(options: CompleteBondingCurveOptions, tx = new Transaction()) {
    console.log('🚀 ~ file: pumpModule.ts:263 ~ PumpModule ~ buildCompleteBondingCurvePayload ~ options:', options)
    const { bonding_curve_id, token_metadata_id, sui_metadata_id, token_coin_type, clmm_global_config_id, clmm_pools_id } = options
    const { pump } = this._sdk.sdkOptions
    const { global_config_id, bonding_curves_id } = getPackagerConfigs(pump)

    tx.moveCall({
      target: `${pump.published_at}::bonding_curve::migrate_liquidity_to_clmm`,
      arguments: [
        tx.object(global_config_id),
        tx.object(bonding_curves_id),
        tx.object(bonding_curve_id),
        tx.object(clmm_global_config_id),
        tx.object(clmm_pools_id),
        tx.object(token_metadata_id),
        tx.object(sui_metadata_id),
        tx.object(CLOCK_ADDRESS)
      ],
      typeArguments: [token_coin_type]
    })

    return tx
  }

  async buildStartBondingCurvePayload(startOptions: StartBondingCurveOptions): Promise<Transaction> {
    const { pump } = this._sdk.sdkOptions
    const { bonding_curve_id, token_coin_type, fee_coin_type, fee_amount, start_cap_id, clmm_pools_id, clmm_config_id, buy_Options, sig } =
      startOptions
    const { global_config_id, bonding_curves_id } = getPackagerConfigs(pump)

    const tx = new Transaction()

    const suiAssetList = await this._sdk.fullClient.getOwnerCoinAssets(this._sdk.senderAddress)
    const payFeeCoinObj = TransactionUtil.buildCoinForAmount(tx, suiAssetList, BigInt(fee_amount), fee_coin_type, false, true)

    // start
    tx.moveCall({
      target: `${pump.published_at}::router::start_bonding_curve`,
      arguments: [
        tx.object(global_config_id),
        tx.object(bonding_curves_id),
        tx.object(start_cap_id),
        tx.object(bonding_curve_id),
        payFeeCoinObj.targetCoin,
        tx.object(clmm_config_id),
        tx.object(clmm_pools_id),
        tx.pure.string(sig)
      ],
      typeArguments: [token_coin_type, fee_coin_type]
    })

    if (buy_Options) {
      const { pay_coin_type, swap_result } = buy_Options
      const { amount_in, amount_out, fee_amount, is_buy, expect_rate_limit, by_amount_in } = swap_result

      const funName = by_amount_in ? 'swap_exact_input_sui' : 'swap_exact_output_meme'

      let pay_amount = '0'
      if (by_amount_in) {
        pay_amount = d(amount_in).add(fee_amount).toFixed(0)
      } else {
        pay_amount = PumpUtils.calculateAmountLimit(is_buy, swap_result)
      }

      const payCoinObj = TransactionUtil.buildCoinForAmount(tx, suiAssetList, BigInt(pay_amount), pay_coin_type, false, true)

      tx.moveCall({
        target: `${pump.published_at}::router::${funName}`,
        arguments: [
          tx.object(global_config_id),
          tx.object(bonding_curve_id),
          payCoinObj.targetCoin,
          tx.pure.u64(by_amount_in ? pay_amount : amount_out),
          tx.pure.u128(expect_rate_limit),
          tx.object(CLOCK_ADDRESS)
        ],
        typeArguments: [token_coin_type]
      })
    }

    return tx
  }
}
