import { useMemo } from 'react'

export function useTextColor({ isLong }: { isLong: boolean }) {
  const color = useMemo(() => {
    return isLong ? 'primary' : 'primary_red'
  }, [isLong])

  const bg = useMemo(() => {
    return isLong ? 'primary_opacity.10' : 'primary_red_opacity.10'
  }, [isLong])

  return {
    color,
    bg
  }
}
