import Icon from '@cetus/ui-kit/src/components/Icon'
import { Box, Image, ImageProps, Stack, Tooltip } from '@chakra-ui/react'
import { useState } from 'react'
import CropImage from './CropImage'
import ImageViewer from './ImageViewer'
import TokenPlaceholder from '/images/token_placeholder.png'
interface PreViewProps extends ImageProps {
  onDelete: (current: any) => void
  editable?: boolean
  onEdit?: (file: any) => void
  file: any
}

const btnStyle = {
  w: { base: '32px', lg: '28px' },
  h: { base: '32px', lg: '28px' },
  bg: 'bg_secondary',
  borderRadius: '8px',
  border: '1px solid',
  borderColor: 'border',
  p: '3px',
  display: { base: 'block', lg: 'none' },
  cursor: 'pointer'
}

function PreView({ src, editable, onEdit, onDelete, file }: PreViewProps) {
  const [editing, setEditing] = useState(false)
  const [fullscreen, setFullScreen] = useState(false)

  const onOk = async (croppedFile: any) => {
    onEdit && (await onEdit({ origin: file, cropped: croppedFile }))
    setEditing(false)
  }

  return (
    <>
      <Box
        display={{ base: 'flex', lg: 'block' }}
        position={{ base: 'static', lg: 'relative' }}
        _hover={{
          div: {
            display: 'flex'
          }
        }}
      >
        <Image
          src={src}
          fallbackSrc={TokenPlaceholder}
          alt="preview"
          objectFit="cover"
          w={{ base: '200px', lg: '160px' }}
          h={{ base: '200px', lg: '160px' }}
          borderRadius="12px"
        />
        <Stack
          flexDir={{ base: 'column', lg: 'row' }}
          position={{ base: 'static', lg: 'absolute' }}
          justify={{ base: 'space-between', lg: 'center' }}
          ml={{ base: '20px', lg: '0' }}
          w="100%"
          gap="12px"
          bottom="8px"
        >
          {editable && (
            <Tooltip label="Edit file">
              <Box
                {...btnStyle}
                onClick={e => {
                  e.stopPropagation()
                  setEditing(!editing)
                }}
              >
                <Icon xlinkHref="#icon-icon_edit" fontSize={{ base: '24px', lg: '20px' }} />
              </Box>
            </Tooltip>
          )}
          <Tooltip label="Preview file">
            <Box
              {...btnStyle}
              onClick={e => {
                e.stopPropagation()
                setFullScreen(!fullscreen)
              }}
            >
              <Icon xlinkHref="#icon-a-icon_zoomout" fontSize={{ base: '24px', lg: '20px' }} />
            </Box>
          </Tooltip>

          <Tooltip label="Remove file">
            <Box
              {...btnStyle}
              onClick={e => {
                e.stopPropagation()
                onDelete(file)
              }}
            >
              <Icon xlinkHref="#icon-icon_del" fontSize={{ base: '24px', lg: '20px' }} />
            </Box>
          </Tooltip>
        </Stack>
      </Box>

      {fullscreen && <ImageViewer src={src as string} open={fullscreen} onClose={() => setFullScreen(false)} />}
      {editing && <CropImage src={src as string} dataUrl={file.dataUrl} file={file} open={editing} onClose={() => setEditing(false)} onOk={onOk} />}
    </>
  )
}

export default PreView
