import { create, StateCreator } from 'zustand'

interface EventState {
  eventList: any
  setEventList: (data: any) => void
  lastThree: any
  setLastThree: (data: any) => void
  marqueePaused: boolean
  setMarqueePaused: (data: boolean) => void

  homeAnimEvent: any
  popHomeAnimEvent: () => any
  pushHomeAnimEvent: (event: any) => void
}

const store: StateCreator<EventState> = (set, get) => ({
  homeAnimEvent: undefined,
  eventList: [],
  setEventList: (data: any) => {
    set(() => ({
      eventList: [...data]
    }))
  },
  lastThree: [],
  setLastThree: (data: any) => {
    set(() => ({
      lastThree: [...data]
    }))
  },
  marqueePaused: false,
  setMarqueePaused: (isPause: boolean) => {
    set(() => ({
      marqueePaused: isPause
    }))
  },
  popHomeAnimEvent: () => {
    const homeAnimEvent = get().homeAnimEvent
    set(() => ({
      homeAnimEvent: undefined
    }))
    return homeAnimEvent
  },
  pushHomeAnimEvent: (event: any) => {
    set(() => ({
      homeAnimEvent: event
    }))
  }
})

const useEventStore = create(store)
export default useEventStore
