import useSwapStore from '@/store/swap/swap'
import useSwapConfigStore from '@/store/swap/swapConfig'
import { AggregatorDex, SwapRouterData } from '@/types/swap'
import { useDebounceFunction, useInitSDK } from '@cetus/hooks'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { CoinInfo } from '@cetus/types'
import { fromDecimalsAmountFix } from '@cetus/utils'
import { FindRouterParams } from '@cetusprotocol/aggregator-sdk'
import { toDecimalsAmount } from '@cetusprotocol/cetus-sui-clmm-sdk'
import BN from 'bn.js'
import { useEffect, useRef, useState } from 'react'
import { v4 } from 'uuid'
import { useGetTokenBalance } from '../../../../hooks/src/useTokenBalance'
import { useGetAmountLimit } from './useSwapHelper'

export function useSwapHook() {
  const {
    fromCoin,
    toCoin,
    setFromCoin,
    setToCoin,
    setToAmount,
    fromAmount,
    toAmount,
    setFromAmount,
    routerData,
    setFindRouterLoading,
    setRouterData,
    setByAmountIn,
    byAmountIn
  } = useSwapStore()
  const { fetchTokenPrices, getTokenAmountValue } = useTokenPrice()
  const { slippage } = useSwapConfigStore()
  const { aggregatorSDK } = useInitSDK()
  const { providersSwitchStates, supportOrderSplit } = useSwapConfigStore()

  // 余额
  const { balanceInfo: fromBalanceInfo } = useGetTokenBalance(fromCoin)
  const { balanceInfo: toBalanceInfo } = useGetTokenBalance(toCoin)

  // 价值
  const fromAmountValue = getTokenAmountValue(fromCoin?.coin_type, fromAmount)
  const toAmountValue = getTokenAmountValue(toCoin?.coin_type, toAmount)

  const [uuid, setUuid] = useState<string>('')

  const uuidRef = useRef<string>('')
  const byAmountInRef = useRef<boolean>(true)
  const fromAmountRef = useRef<string>('')
  const toAmountRef = useRef<string>('')

  useEffect(() => {
    uuidRef.current = uuid
  }, [uuid])

  useEffect(() => {
    byAmountInRef.current = byAmountIn
  }, [byAmountIn])

  useEffect(() => {
    fromAmountRef.current = fromAmount
  }, [fromAmount])

  useEffect(() => {
    toAmountRef.current = toAmount
  }, [toAmount])

  /**
   * 预计算
   */
  const findRouters = async (amount: string, by_amount_in: boolean, uuid: string) => {
    if (fromCoin && toCoin && +amount) {
      const providersKeys = Object.entries(providersSwitchStates)
        .filter(([_, value]) => value === true)
        .map(([key, _]) => key)

      const formatAmount = toDecimalsAmount(amount, fromCoin.decimals)
      const routerParams: FindRouterParams = {
        from: fromCoin.coin_type,
        target: toCoin.coin_type,
        amount: new BN(formatAmount),
        byAmountIn: by_amount_in,
        depth: 3,
        splitAlgorithm: undefined,
        splitFactor: undefined,
        splitCount: supportOrderSplit ? undefined : 1,
        providers: providersKeys
      }

      console.log('🚀 ~ file: useSwap.ts:26 ~ findRouters ~ routerParams:', routerParams)
      try {
        setFindRouterLoading(true)
        const res = await aggregatorSDK.findRouters(routerParams)
        console.log('🚀 ~ file: useSwap.ts:45 ~ findRouters ~ res:', res)
        const providerMap: Record<string, AggregatorDex> = {}
        if (res) {
          const toAmountUi = fromDecimalsAmountFix(res.amountOut.toString(), toCoin.decimals).toString()
          const fromAmountUi = fromDecimalsAmountFix(res.amountIn.toString(), fromCoin.decimals).toString()
          const result: SwapRouterData = {
            routerData: res,
            fromAmountUi,
            toAmountUi,
            providers: Object.values(providerMap),
            uuid,
            byAmountIn: by_amount_in,
            isExceed: false,
            isDegrade: false
          }

          console.log('🚀 ~ file: useSwap.ts:113 ~ findRouters ~ result:', result)

          if (uuidRef.current === result.uuid) {
            if (by_amount_in) {
              if (+fromAmountRef.current) {
                setToAmount(toAmountUi)
                setRouterData(result)
              } else {
                setToAmount('')
              }
            } else {
              if (+toAmountRef.current) {
                setFromAmount(fromAmountUi)
                setRouterData(result)
              } else {
                setFromAmount('')
              }
            }
          }
        }
      } catch (error) {
        console.log('🚀 ~ file: useSwap.ts:135 ~ findRouters ~ error:', error)

        setToAmount('')
      } finally {
        setFindRouterLoading(false)
      }
    } else {
      setToAmount('')
      setRouterData(undefined)
      setFindRouterLoading(false)
    }
  }
  const debouncedFindRouters = useDebounceFunction(findRouters, 500)

  // 输入不合法 清空router data
  useEffect(() => {
    if (+fromAmountRef.current && +toAmountRef.current) {
      return
    }
    setRouterData(undefined)
  }, [fromAmount, toAmount])

  /**
   * 输入数量监听
   * @param amount
   */
  const handleAmountChange = (amount: string, by_amount_in: boolean, resetInput: boolean = false) => {
    setByAmountIn(by_amount_in)
    if (by_amount_in) {
      setFromAmount(amount)
      if (resetInput) {
        setToAmount('')
      }
    } else {
      setToAmount(amount)
      if (resetInput) {
        setFromAmount('')
      }
    }

    if (+amount) {
      const uuid = v4()
      setUuid(uuid)
      debouncedFindRouters(amount, by_amount_in, uuid)
    } else {
      setFindRouterLoading(false)
      setRouterData(undefined)
      resetInputAmount()
    }
  }

  /**
   * 重新计算RouteData
   */
  const reCalculateRouteData = () => {
    const amount = byAmountInRef.current ? fromAmountRef.current : toAmountRef.current

    if (+amount) {
      const uuid = v4()
      setUuid(uuid)
      debouncedFindRouters(amount, byAmountInRef.current, uuid)
    }
  }

  /**
   * 切换token监听
   * @param coin
   * @param isFrom
   */
  const handleSelectToken = (coin: CoinInfo, isFrom: boolean) => {
    resetInputAmount()
    if (isFrom) {
      if (coin.coin_type === toCoin?.coin_type) {
        setToCoin(undefined)
      }
      setFromCoin(coin)
    } else {
      if (coin.coin_type === fromCoin?.coin_type) {
        setFromCoin(undefined)
      }
      setToCoin(coin)
    }
  }

  const { amountLimit } = useGetAmountLimit(slippage, routerData)

  const resetInputAmount = () => {
    setFromAmount('')
    setToAmount('')
  }

  // 监听token 切换 刷新价格
  useEffect(() => {
    const list = []
    if (fromCoin) {
      list.push(fromCoin.coin_type)
    }

    if (toCoin) {
      list.push(toCoin.coin_type)
    }

    if (list.length > 0) {
      fetchTokenPrices(list)
    }
  }, [fromCoin?.coin_type, toCoin?.coin_type])

  const getSwapSecondaryData = () => {
    return { ...routerData! }
  }

  return {
    handleSelectToken,
    handleAmountChange,
    fromAmount,
    toAmount,
    fromAmountValue,
    toAmountValue,
    amountLimit,
    getSwapSecondaryData,
    reCalculateRouteData,
    fromBalanceInfo,
    toBalanceInfo
  }
}
