import { ToastType } from '@cetus/types/src/common-types'
import { Icon } from '@cetus/ui-kit'
import { Center, HStack, Link, VStack } from '@chakra-ui/react'
import { useMemo } from 'react'
import { ToastDescription } from './ToastDescription'
import { ToastTitle } from './ToastTitle'

type ToastProps = {
  onClose?: () => void
} & ToastType

export default function Toast(props: ToastProps) {
  const { status = 'confirmation', link, getShowInfo, linkLabel = 'View transaction', onClose } = props

  // console.log('🚀 ~ file: Toast.tsx:12 ~ Toast ~ props:', props)

  const showInfo = useMemo(() => {
    if (getShowInfo) {
      return getShowInfo(status)
    }
    return undefined
  }, [status])

  return (
    <HStack
      w="440px"
      // minH="104px"
      // maxW="440px"
      bg="background"
      border="1px"
      borderColor="border"
      borderRadius="12px"
      p="16px"
      position="relative"
      gap="16px"
      sx={{
        '@media screen and (max-width: 810px)': {
          w: '330px',
          minW: '330px',
          p: '16px'
        }
      }}
    >
      <VStack w="100%" alignItems="start">
        {/* 标题 */}
        <ToastTitle info={showInfo} status={status} />

        {/* 描述 */}
        {(showInfo?.toastDescriptionContent || link) && <ToastDescription info={showInfo} status={status} link={link} />}

        {/* 区块游览器 */}
        {status !== 'submitted' && link && (
          <Link href={link} target="_blank" color="primary_green" fontSize="sm" textDecoration={status === 'success' ? 'none' : 'none'}>
            {linkLabel}
          </Link>
        )}
      </VStack>

      {/* 关闭按钮 */}
      <Center onClick={onClose} position="absolute" right="16px" top="16px">
        <Icon xlinkHref="#icon-icon_close" variant="gray" />
      </Center>
    </HStack>
  )
}
