import envConfigs from '@cetus/types/src/config/envConfigs'
import { create, StateCreator } from 'zustand'

interface GlobalApiSDomainState {
  domains: string[]
  unhealthyDomains: string[]
  currentDomain: string
  setCurrentDomain: (value: string) => void
  setUnhealthyDomains: (value: string) => void
}

const store: StateCreator<GlobalApiSDomainState> = (set, get) => ({
  domains: [envConfigs.cetus_api],
  unhealthyDomains: [],
  currentDomain: envConfigs.cetus_api,
  setCurrentDomain: (value: string) => {
    set(() => ({
      currentDomain: value
    }))
  },
  setUnhealthyDomains: (value: string) => {
    set(() => ({
      unhealthyDomains: [...get().unhealthyDomains, value]
    }))
  }
})

export const useGlobalApiDomainStore = create(store)
