import envConfigs from '@cetus/types/src/config/envConfigs'
import { AggregatorClient, Env } from '@cetusprotocol/aggregator-sdk'
import { CetusClmmSDK } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { SuiClient } from '@mysten/sui/client'
import { StateCreator, create } from 'zustand'

interface SDKState {
  clmmSdk: CetusClmmSDK
  setClmmSdk: (clmmSdk: CetusClmmSDK) => void

  aggregatorSDK: AggregatorClient
  setAggregatorSDK: (client: AggregatorClient) => void
}

const store: StateCreator<SDKState> = (set, get) => ({
  clmmSdk: new CetusClmmSDK(envConfigs.clmm_sdk_options),
  aggregatorSDK: new AggregatorClient(
    envConfigs.clmm_sdk_options.aggregatorUrl,
    envConfigs.clmm_sdk_options.simulationAccount.address,
    new SuiClient({ url: envConfigs.clmm_sdk_options.fullRpcUrl }),
    envConfigs.env === 'testnet' ? Env.Testnet : Env.Mainnet
  ),
  setClmmSdk: (clmmSdk: CetusClmmSDK) => {
    set(() => ({
      clmmSdk
    }))
  },
  setAggregatorSDK: (client: AggregatorClient) => {
    set(() => ({
      aggregatorSDK: client
    }))
  }
})

const useClmmSDKStore = create(store)
export default useClmmSDKStore
