import { PumpToken } from '@/type/pump'
import { StateCreator, create } from 'zustand'
import { persist } from 'zustand/middleware'

interface PumpTokenListState {
  cachePumpTokenList: PumpToken[]
  setCachePumpTokenList: (list: PumpToken[]) => void
}

const store: StateCreator<PumpTokenListState> = (set, get) => ({
  cachePumpTokenList: [],
  setCachePumpTokenList: (list: PumpToken[]) => {
    set(state => ({
      cachePumpTokenList: list
    }))
  }
})

const usePumpTokenListCacheStore = create(persist(store, { name: 'usePumpTokenListCacheStore', version: 1 }))
export default usePumpTokenListCacheStore
