import Icon from '@cetus/ui-kit/src/components/Icon'
import { addressAbridge, cancelBubble } from '@cetus/utils'
import { Button, HStack, Popover, PopoverContent, PopoverTrigger, Text, useDisclosure, VStack } from '@chakra-ui/react'
import { useSwitchAccount } from '@mysten/dapp-kit'
import { useRef } from 'react'
import { AccountSwitchProps } from './type'

export default function AccountSwitch(props: AccountSwitchProps) {
  const { mutate: switchAccount } = useSwitchAccount()
  const { currentAccount, accounts, onClose: onOuterClose } = props
  const ref = useRef()
  const { isOpen, onToggle, onClose } = useDisclosure()
  return (
    <HStack>
      {accounts.length === 1 && (
        <Text fontSize="20px" color="text_caption">
          {addressAbridge(currentAccount.address)}
        </Text>
      )}
      {accounts.length > 1 && (
        <Popover isOpen={isOpen} onClose={onClose} placement="bottom-start">
          <PopoverTrigger>
            <Button variant="unstyled" bg="transparent" display="flex" onClick={onToggle}>
              <Text fontSize="20px" color="text_caption">
                {addressAbridge(currentAccount.address)}
              </Text>
              {accounts.length > 1 && (
                <Icon
                  xlinkHref="#icon-icon_descending"
                  svgW="20px"
                  svgH="20px"
                  transform={isOpen ? 'rotate(-180deg)' : 'rotate(0deg)'}
                  transition="transform 0.3s"
                />
              )}
            </Button>
          </PopoverTrigger>
          {isOpen && (
            <PopoverContent
              ref={ref as any}
              w="330px"
              bg="bg_secondary"
              borderRadius="8px"
              p="0px"
              border="1px solid"
              borderColor="border"
              position="fixed"
              left="-18px"
              top="8px"
              zIndex="1000"
              h="100px"
              overflow="scroll"
            >
              <VStack w="100%" p="18px" gap="20px">
                {accounts.map(account => {
                  return (
                    <HStack key={account.address} w="100%" justifyContent="space-between">
                      <Text fontSize="14px" color="text_caption">
                        {addressAbridge(account.address)}
                      </Text>
                      <Button
                        onClick={e => {
                          cancelBubble(e)
                          switchAccount({ account })
                          onClose()
                          onOuterClose()
                        }}
                        disabled={account.address === currentAccount.address}
                        color="text_highlight"
                        h="22px"
                        variant="outline"
                        borderRadius="4px"
                        fontSize="12px"
                      >
                        Switch
                      </Button>
                    </HStack>
                  )
                })}
              </VStack>
            </PopoverContent>
          )}
        </Popover>
      )}
    </HStack>
  )
}
