import { useTransactionStore } from '@cetus/stores/src'
import { ToastType } from '@cetus/types/src/common-types'

export default function useTransactionModal() {
  const { setTransactionData, setTransactionModalVisible, transactionModalVisible } = useTransactionStore()
  const transactionConfirmation = (props: ToastType) => {
    setTransactionData({
      ...props,
      status: 'confirmation'
    })
    setTransactionModalVisible(true)
  }

  const transactionSubmitted = (props: ToastType) => {
    setTransactionModalVisible(false)
    setTransactionData({
      ...props,
      status: 'submitted'
    })
    setTransactionModalVisible(true)
  }

  const transactionSuccess = (props: ToastType) => {
    setTransactionModalVisible(false)
    setTransactionData({
      ...props,
      status: 'success'
    })
    setTransactionModalVisible(true)
  }

  const transactionRejected = (props: ToastType) => {
    setTransactionModalVisible(false)
    setTransactionData({
      ...props,
      status: 'rejected'
    })
    setTransactionModalVisible(true)
  }

  return { transactionConfirmation, transactionSubmitted, transactionSuccess, transactionRejected }
}
