import { Button, Image, StackProps, Text, VStack } from '@chakra-ui/react'
import React from 'react'
import { default as img_nodata, default as nowallet } from './assets/images/img_nopositions@2x.png'

interface NoDataProps extends StackProps {
  type: 'nowallet' | 'nodata' | ''
  noBorder?: boolean
  children?: React.ReactNode
  onboard?: () => void
  text?: string
}

export default function NoData(props: NoDataProps) {
  const { type, noBorder, text, children, onboard, ...rest } = props
  return (
    <VStack
      w="100%"
      h="auto"
      background="bg_secondary"
      gap="4px"
      p="40px"
      align="center"
      justifyContent="center"
      borderRadius="12px"
      border="1px solid"
      borderColor={noBorder ? 'transparent' : 'border'}
      {...rest}
    >
      <Image w="200px" h="200px" src={type == 'nodata' ? img_nodata : type == 'nowallet' ? nowallet : ''} />
      {type == 'nowallet' ? (
        <Button borderRadius="8px" w="120px" h="28px" fontSize="xs" onClick={onboard}>
          Connect Wallet
        </Button>
      ) : (
        <Text color="text_caption" textAlign="center" fontWeight="500">
          {!text ? 'No Data' : text}
        </Text>
      )}
      {children}
    </VStack>
  )
}
