import { WalletAccount } from '@wallet-standard/base'
import { create } from 'zustand'

interface AccountState {
  accounts: WalletAccount[]
  currentAccount: WalletAccount | undefined
  saveCurrentAccount: (account: WalletAccount | undefined) => void
  saveAccounts: (accounts: WalletAccount[]) => void
  isOpenWalletModal: boolean
  onWalletModal: (isOpen: boolean) => void
}

const useAccountStore = create<AccountState>((set, get) => ({
  accounts: [],
  currentAccount: undefined,
  isOpenWalletModal: false,
  saveCurrentAccount: (account: WalletAccount | undefined) => {
    set({
      currentAccount: account
    })
  },
  saveAccounts: (accounts: WalletAccount[]) => {
    set({
      accounts
    })
  },
  onWalletModal: (isOpen: boolean) => {
    set({
      isOpenWalletModal: isOpen
    })
  }
}))

export { useAccountStore }
