import { Box, HTMLChakraProps } from '@chakra-ui/react'
import React from 'react'

interface BlockProps extends HTMLChakraProps<'div'> {
  children: React.ReactNode
}

function Block({ children, ...rest }: BlockProps) {
  return (
    <Box as="div" w="100%" borderRadius="20px" border="1px solid" borderColor="border" bg="bg_secondary" p="20px 16px" {...rest}>
      {children}
    </Box>
  )
}

export default Block
