import { d, getDeltaDownFromOutput, getDeltaUpFromInput } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { BondingCurveStatus, PumpUtils } from '@cetusprotocol/cetus-sui-pump-sdk'
import BN from 'bn.js'
import Decimal from 'decimal.js'
import { useMemo } from 'react'
import { useGetGlobalConfig } from './useGetGlobalConfig'

export function useGetMaxAmount(
  liquidity?: string,
  curSqrtPrice?: string,
  lowerSqrtPrice?: string,
  upperSqrtPrice?: string,
  status?: BondingCurveStatus
) {
  const { globalConfig } = useGetGlobalConfig()

  const buyMaxAmountIn = useMemo(() => {
    if (status && status >= BondingCurveStatus.MIGRATED) {
      return '0'
    }

    if (liquidity && curSqrtPrice && upperSqrtPrice && globalConfig) {
      try {
        const max_amount_in = getDeltaUpFromInput(new BN(curSqrtPrice), new BN(upperSqrtPrice), new BN(liquidity), false).toString()
        const feeAmount = PumpUtils.getFeeAmount(max_amount_in, Number(globalConfig.swap_fee_rate))
        return d(max_amount_in).add(feeAmount).toFixed(0, Decimal.ROUND_UP)
      } catch (error) {
        console.log('🚀 ~ file: useGetMaxAmount.ts:44 ~ buyMaxAmountIn ~ error:', error)
      }
    }
    return '0'
  }, [liquidity, curSqrtPrice, upperSqrtPrice, status, globalConfig])

  const buyMaxAmountOut = useMemo(() => {
    if (status && status >= BondingCurveStatus.MIGRATED) {
      return '0'
    }
    if (curSqrtPrice && upperSqrtPrice && liquidity) {
      try {
        const max_amount_out = getDeltaDownFromOutput(new BN(curSqrtPrice), new BN(upperSqrtPrice), new BN(liquidity), false).toString()
        return max_amount_out.toString()
      } catch (error) {
        console.log('🚀 ~ file: useGetMaxAmount.ts:52 ~ buyMaxAmountOut ~ error:', error)
      }
    }
    return '0'
  }, [liquidity, curSqrtPrice, upperSqrtPrice, status])

  const sellMaxAmountIn = useMemo(() => {
    if (status && status >= BondingCurveStatus.MIGRATED) {
      return '0'
    }
    if (curSqrtPrice && lowerSqrtPrice && liquidity) {
      try {
        const max_amount_in = getDeltaUpFromInput(new BN(curSqrtPrice), new BN(lowerSqrtPrice), new BN(liquidity), true).toString()
        return max_amount_in.toString()
      } catch (error) {
        console.log('🚀 ~ file: useGetMaxAmount.ts:52 ~ sellMaxAmountIn ~ error:', error)
      }
    }
    return '0'
  }, [liquidity, curSqrtPrice, lowerSqrtPrice, status])

  const sellMaxAmountOut = useMemo(() => {
    if (status && status >= BondingCurveStatus.MIGRATED) {
      return '0'
    }
    if (curSqrtPrice && lowerSqrtPrice && liquidity) {
      try {
        const max_amount_out = getDeltaDownFromOutput(new BN(curSqrtPrice), new BN(lowerSqrtPrice), new BN(liquidity), true).toString()
        return max_amount_out.toString()
      } catch (error) {
        console.log('🚀 ~ file: useGetMaxAmount.ts:52 ~ sellMaxAmountOut ~ error:', error)
      }
    }
    return '0'
  }, [liquidity, curSqrtPrice, lowerSqrtPrice, status])

  return {
    buyMaxAmountIn,
    buyMaxAmountOut,
    sellMaxAmountIn,
    sellMaxAmountOut
  }
}
