import { Box } from '@chakra-ui/react'
import { addComma } from '@cetus/utils'

const formatCurrency = (value: string) => {
  try {
    const isNegative = value.startsWith('-')
    return isNegative ? `-$${value.slice(1)}` : `$${value}`
  } catch (error) {
    console.log('🚀 ~ formatCurrency ~ error:', error)
    return '$--'
  }
}

export default function Comma({ value, currency }: { value: string | number; currency?: boolean }) {
  const _value = (currency ? formatCurrency(value + '') : value) + ''
  const _index = (_value + '').indexOf('$')

  const array = _index > -1 ? (addComma(_value.slice(_index + 1)) + '').split(',') : (addComma(_value) + '').split(',')
  const length = array.length

  return (
    <Box as="span">
      {_index > -1 && _value.slice(0, _index + 1)}
      {array.map((item, index) => (
        <Box as="span" key={`${item}-${index}`}>
          {item}
          {index < length - 1 && (
            <Box as="span" className="delimiter">
              ,
            </Box>
          )}
        </Box>
      ))}
    </Box>
  )
}
