import { ErrorBoundary } from '@cetus/design'
import { useGetTokens } from '@cetus/hooks'
import useGlobalStore from '@cetus/stores/src/global'
import { theme } from '@cetus/ui-kit'
import { ChakraProvider } from '@chakra-ui/react'
import { lazy, useEffect } from 'react'
import { useLocation } from 'react-router-dom'

const PumpLayout = lazy(() => import('@cetus/pump/src/layout'))
const CetusLayout = lazy(() => import('./CetusLayout'))
export default function Layout() {
  const { pathname } = useLocation()
  const isPump = ['/home', '/trade', '/create', '/ranking', '/profile', '/trade', '/test'].some(path => pathname.startsWith(path))
  const { globalLoading, setGlobalLoading } = useGlobalStore()
  const { getTokens } = useGetTokens()
  useEffect(() => {
    setTimeout(() => {
      setGlobalLoading(false)
    }, 1000)

    getTokens()
  }, [])
  return (
    <ErrorBoundary>
      <ChakraProvider theme={theme}>
        {isPump ? <PumpLayout /> : <CetusLayout />}
        {/* <PumpLayout /> */}
      </ChakraProvider>
    </ErrorBoundary>
  )
}
