import useRpcConfigStore from '@cetus/stores/src/useRpcConfigStore'
import envConfigs from '@cetus/types/src/config/envConfigs'

export type ExplorerType = 'account' | 'token' | 'tx' | 'poolAddress' | 'nftAddress' | 'coin'

export default function useExplorer() {
  const { currentExplorer } = useRpcConfigStore()

  const getExplorerUrl = (address?: string, type: ExplorerType = 'account') => {
    const urlName =
      currentExplorer.name.toLocaleLowerCase().indexOf('suivision') > -1
        ? 'SuiVision'
        : currentExplorer.name.toLocaleLowerCase().indexOf('suiscan') > -1
          ? 'Suiscan'
          : ''
    let href
    if (urlName == 'SuiVision') {
      href = `${currentExplorer.link}/${getSuiVisionKey(type)}/${address}`
    } else {
      href = `${currentExplorer.link}/${envConfigs.env}/${getSuiscanKey(type)}/${address}`
    }
    return href
  }

  return { getExplorerUrl }
}

const getSuiscanKey = (type: ExplorerType) => {
  switch (type) {
    case 'account':
      return 'address'
    case 'token':
      return 'object'
    case 'tx':
      return 'tx'
    case 'poolAddress':
      return 'object'
    case 'nftAddress':
      return 'object'
    case 'coin':
      return 'coin'
  }
}
const getSuiVisionKey = (type: ExplorerType) => {
  switch (type) {
    case 'account':
      return 'account'
    case 'token':
      return 'object'
    case 'tx':
      return 'txblock'
    case 'poolAddress':
      return 'object'
    case 'nftAddress':
      return 'object'
    case 'coin':
      return 'coin'
  }
}
