import { useGlobalApiDomainStore } from '@cetus/stores'
import { fetchGet, fetchPost } from '@cetus/utils'

export const useFetch = () => {
  const { domains, currentDomain, setCurrentDomain, setUnhealthyDomains, unhealthyDomains } = useGlobalApiDomainStore()

  // 获取domain策略(如有需要, 后期可以增加不健康域名过期时间等复杂逻辑)
  const getDomain = () => {
    const domainsLen = domains.length
    if (domainsLen > 1 && unhealthyDomains.length < domainsLen - 1) {
      setUnhealthyDomains(currentDomain)
      const currentDomainIndex = domains.indexOf(currentDomain)
      let newDomain = ''
      if (currentDomainIndex !== domainsLen - 1) {
        newDomain = domains[currentDomainIndex + 1]
      } else {
        newDomain = domains[0]
      }

      return newDomain
    }
    return ''
  }

  const fetchByApi = async (path: string, type: 'GET' | 'POST', options?: any, doamin?: string) => {
    console.log('🚀 ~ file: useFetch.ts:30 ~ fetchByApi ~ params:', {
      path,
      type,
      options,
      domain: doamin || currentDomain
    })
    try {
      const response =
        type === 'GET' ? await fetchGet(`${doamin || currentDomain}${path}`, options) : await fetchPost(`${doamin || currentDomain}${path}`, options)
      return response
    } catch (error) {
      console.log('🚀 ~ file: useFetch.ts:41 ~ fetchByApi ~ error:', error)
      const newDomain = getDomain()
      if (newDomain) {
        setCurrentDomain(newDomain)
        return fetchByApi(path, type, options, newDomain)
      }
      throw error
    }
  }

  return {
    fetchByApi
  }
}
