import { RouterData } from '@cetusprotocol/aggregator-sdk'

export enum AggregatorProvider {
  CETUS = 'CETUS',
  DEEPBOOK = 'DEEPBOOK',
  KRIYA = 'KRIYA',
  KRIYAV3 = 'KRIYAV3',
  FLOWX = 'FLOWX',
  FLOWXV3 = 'FLOWXV3',
  AFTERMATH = 'AFTERMATH',
  HAEDAL = 'HAEDAL',
  VOLO = 'VOLO',
  AFSUI = 'AFSUI',
  DEEPBOOKV3 = 'DEEPBOOKV3',
  SCALLOP = 'SCALLOP',
  BLUEMOVE = 'BLUEMOVE',
  TURBOS = 'TURBOS'
}

export type AggregatorDex = {
  name: string
  id: AggregatorProvider
  logo: string
  type: string
  sort: number
  subItems?: AggregatorDex[]
}

export type SwapRouterData = {
  routerData: RouterData
  fromAmountUi: string
  toAmountUi: string
  byAmountIn: boolean
  isExceed: boolean // 是否超出流动性
  isDegrade: boolean //是否是降级
  uuid: string
}

export type SwapRouterFormat = {
  router_summery: string
  providers: AggregatorProvider[]
  routers: {
    percentage: string
    paths: {
      from_type: string
      to_type: string
      fee_rate: string
      provider: AggregatorProvider
    }[]
  }[]
}
