import { CreateTokenModelOptions } from '@/type/pump'
import { Heading, Modal, ModalBody, ModalCloseButton, ModalContent, ModalHeader, ModalOverlay } from '@chakra-ui/react'
import { CreateTokenStepOne } from './CreateTokenStepOne'
import { CreateTokenStepTwo } from './CreateTokenStepTwo'

type CreateTokenModelProps = {
  options: CreateTokenModelOptions
  isOpen: boolean
  onClose: () => void
}

export default function CreateTokenModel(props: CreateTokenModelProps) {
  const { isOpen, onClose, options } = props
  const { tokenTicker, stepIndex, status } = options
  return (
    <Modal isOpen={isOpen} onClose={onClose}>
      <ModalOverlay />
      <ModalContent>
        <ModalHeader>
          <Heading fontWeight="500" fontSize="16px">
            {`Create ${tokenTicker} Token`}
          </Heading>
        </ModalHeader>
        <ModalCloseButton />
        <ModalBody pb="30px" textAlign="center">
          {/* 第一步 */}
          {stepIndex === 1 && <CreateTokenStepOne options={options} onClose={onClose} />}
          {/* 第二步 */}
          {stepIndex === 2 && <CreateTokenStepTwo options={options} onClose={onClose} />}
        </ModalBody>
      </ModalContent>
    </Modal>
  )
}
