import { CoinInfo } from '@cetus/types/src/common-types'
import { LocalStorageService } from '@cetus/utils'
import { extractStructTagFromType } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { StateCreator, create } from 'zustand'

interface TokenState {
  //当前正在请求token
  requestTokenList: string[]
  addRequestTokenList: (coinType: string) => void

  setToken: (info: CoinInfo) => void
  tokenMap: Map<string, CoinInfo>
  setTokenMap: (data: Map<string, CoinInfo>) => void
}

const store: StateCreator<TokenState> = (set, get) => {
  return {
    requestTokenList: [],
    addRequestTokenList: (coinType: string) => {
      set(() => ({
        requestTokenList: [...get().requestTokenList, coinType]
      }))
    },

    setToken: (info: CoinInfo) => {
      const { tokenMap, requestTokenList } = get()
      const newTokenMap = new Map(tokenMap)
      newTokenMap.set(extractStructTagFromType(info.coin_type).full_address, info)

      // 从请求队列移除
      const newList = requestTokenList.filter(type => type !== info.coin_type)
      set(() => ({
        tokenMap: newTokenMap,
        requestTokenList: [...newList]
      }))
      //TODO 单个存储 更新全量tokenMap  是否存在性能问题?
      LocalStorageService.setItem('tokenMap', newTokenMap)
    },
    tokenMap: new Map<string, CoinInfo>(),
    setTokenMap: (data: Map<string, any>) => {
      set(() => ({
        tokenMap: data
      }))
      LocalStorageService.setItem('tokenMap', data)
    }
  }
}

// const useTokenStore = create(persist(store, { name: 'useTokenStore', version: 2 }))
// export default useTokenStore

const useTokenStore = create(store)
export default useTokenStore

// 从 localForage 加载数据
LocalStorageService.getItem<any>('tokenMap').then(savedTokenMap => {
  console.log('🚀 ~ file: token.ts:57 ~ savedTokenMap:', savedTokenMap)
  if (savedTokenMap !== null) {
    useTokenStore.getState().setTokenMap(savedTokenMap)
  }
})

