import { create, StateCreator } from 'zustand'

interface globalState {
  globalLoading: boolean
  setGlobalLoading: (value: boolean) => void
  isScrollTop: boolean
  setIsScrollTop: (value: boolean) => void
}

const store: StateCreator<globalState> = (set, get) => ({
  globalLoading: true,
  setGlobalLoading: (value: boolean) => {
    set(() => ({
      globalLoading: value
    }))
  },
  isScrollTop: true,
  setIsScrollTop: (value: boolean) => {
    set(() => ({
      isScrollTop: value
    }))
  }
})

const useGlobalStore = create(store)
export default useGlobalStore
