import useTokenBalanceStore from '@cetus/stores/src/tokenBalance'
import { CoinInfo } from '@cetus/types/src/common-types'
import { extractStructTagFromType, fromDecimalsAmount } from '@cetusprotocol/cetus-sui-clmm-sdk'
import Decimal from 'decimal.js'
import { useMemo } from 'react'
import { useAccountBalance } from '.'
import { formatNumber } from '../../utils/src/formatter'

export function useGetTokenBalance(coin?: CoinInfo) {
  const { tokenBalanceObj } = useTokenBalanceStore()
  const { fetchCoinBalance } = useAccountBalance()

  const balanceInfo = useMemo(() => {
    if (coin) {
      const info = tokenBalanceObj[extractStructTagFromType(coin.coin_type).full_address]

      if (info) {
        console.log('🚀 ~ file: useTokenBalance.ts:15 ~ balanceInfo ~ info:', info)

        const totalBalance = info.totalBalance
        const balanceFormat = fromDecimalsAmount(totalBalance, coin.decimals).toString()
        return {
          balance: info.totalBalance,
          balanceFormat,
          balanceDisplay: formatNumber(balanceFormat, undefined, undefined, Decimal.ROUND_DOWN)
        }
      }
      return undefined
    }

    return undefined
  }, [coin?.coin_type, tokenBalanceObj])

  return {
    balanceInfo,
    fetchCoinBalance
  }
}
