import { suiPriorityConfigs } from '@/constant/sui-priority'

export function isForward(coinTypeA: string, coinTypeB: string): boolean {
  const indexA = suiPriorityConfigs.indexOf(coinTypeA)
  const indexB = suiPriorityConfigs.indexOf(coinTypeB)

  if (indexA === -1 && indexB === -1) {
    return true
  }

  if (indexA !== -1 && indexB === -1) {
    return false
  }

  if (indexA === -1 && indexB !== -1) {
    return true
  }

  return indexA > indexB
}
